/// <reference types="react" />
import { z } from 'zod';
import { BreadCrumbConfigSchema, BreadcrumbItemSchema, CountrySchema, VendorSchema } from './headerConfig.schema';
export type DropdownButton = {
    onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
    label: string;
    icon: () => React.ReactNode;
    disabled?: boolean;
    options?: [Button?, Button?, Button?];
};
export type Button = {
    onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
    label: string;
    icon: () => React.ReactNode;
    disabled?: boolean;
};
export type OptionalButton = DropdownButton & Button;
export type BreadcrumbItem = z.infer<typeof BreadcrumbItemSchema>;
export type BreadCrumbConfig = z.infer<typeof BreadCrumbConfigSchema>;
export type Vendor = z.infer<typeof VendorSchema>;
export type Country = z.infer<typeof CountrySchema>;
export interface AppHeaderConfig extends AppHeaderConfigPayload {
    loadingVendors: boolean;
    vendorOptions: Vendor[];
    countryOptions: Country[];
    selectedCountry?: Country;
    selectedVendor?: string;
    optionalButtons?: [OptionalButton?, OptionalButton?];
    pageTitle?: string;
}
export type AppHeaderConfigPayload = {
    breadcrumbConfig?: BreadCrumbConfig;
    countryOptions?: Country[];
    countrySelect?: boolean;
    vendorSelect?: boolean;
    defaultCountry?: Country;
    defaultVendor?: string;
    disableCountrySelect?: boolean;
    disableVendorSelect?: boolean;
    optionalButtons?: [OptionalButton?, OptionalButton?];
    pageTitle?: string;
};
